// Terminal Trails: the complete Hike Trail foundation expedition.
// Every network target, account, log, and incident in this course is a simulation.
const HOME = '/home/trainee';
const path = (relative) => `${HOME}/${relative}`;
const read = (id, label, detail, relative) => ({ id, label, detail, check: { type: 'read', path: path(relative) } });
const command = (id, label, detail, name, argsIncludes = [], outputIncludes = []) => ({
  id, label, detail, check: { type: 'command', name, argsIncludes, outputIncludes },
});
const write = (id, label, detail, relative, contains) => ({
  id, label, detail, check: { type: 'write', path: path(relative), contains },
});
const frame = (speaker, title, text) => ({ speaker, title, text });
const option = (id, label, correct, feedback) => ({ id, label, correct, feedback });
const difficulties = ['Getting started', 'Finding your feet', 'Field ready', 'Final expedition'];
function mission(data) {
  const correct = data.decision.options.find((item) => item.correct);
  return {
    estimate: '4–6 min',
    difficulty: difficulties[data.act],
    ...data,
    objectives: [
      ...data.objectives,
      { id: 'decision', label: data.decision.title, detail: 'Use the evidence you collected to choose your next move.', check: { type: 'decision', value: correct.id } },
    ],
  };
}

